import NavbarPillGlide from '@/components/tweenui/navbar-pill-glide';

export default function Layout({ children }: { children: React.ReactNode }) {
  return (
    <NavbarPillGlide
      brand="Kairo"
      currentHref="/pricing"
      email="hello@kairo.studio"
      primaryAction={{ label: 'Start free', href: '/signup' }}
      secondaryAction={{ label: 'Book a demo', href: '/demo' }}
      links={[
        { label: 'Home', href: '/', image: '/menu/home.jpg' },
        { label: 'Customers', href: '/customers', image: '/menu/customers.jpg' },
        { label: 'Pricing', href: '/pricing', image: '/menu/pricing.jpg' },
        { label: 'Journal', href: '/journal', image: '/menu/journal.jpg' },
      ]}
    >
      {children}
    </NavbarPillGlide>
  );
}
